<?php
require_once __DIR__.'/Controller.php'; require_once __DIR__.'/../models/Penyaluran.php'; require_once __DIR__.'/../models/JurnalKas.php';
class PenyaluranController extends Controller {public function __construct(){$this->guard();}
 public function edit():void{$this->index();}
 public function index():void{$m=new Penyaluran();$err=null;$action=$_GET['action']??'index';$edit=null;$id=(int)($_GET['id']??0);if($action==='edit'){$edit=$m->getById($id);if(!$edit){flash('Data penyaluran tidak ditemukan.','err');redirect('index.php?page=penyaluran');}}
 if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$pa=$_POST['form_action']??'create';if($pa==='delete'){$m->delete((int)($_POST['id']??0));flash('Penyaluran dan jurnal terkait berhasil dihapus.');redirect('index.php?page=penyaluran');}$d=['tanggal'=>trim($_POST['tanggal']??''),'nama_mustahik'=>trim($_POST['nama_mustahik']??''),'asnaf'=>trim($_POST['asnaf']??'Fakir'),'pos_dana'=>trim($_POST['pos_dana']??''),'nominal'=>(float)($_POST['nominal']??0),'keterangan'=>trim($_POST['keterangan']??'')];if(!tanggal_valid($d['tanggal']))throw new RuntimeException('Tanggal penyaluran tidak valid.');if($d['nama_mustahik']==='')throw new RuntimeException('Nama mustahik/penerima wajib diisi.');if(!in_array($d['asnaf'],['Fakir','Miskin','Sumbangan'],true))throw new RuntimeException('Pilihan asnaf tidak valid.');if(!array_key_exists($d['pos_dana'],JurnalKas::POS))throw new RuntimeException('Pos dana tidak valid.');if($d['nominal']<=0||$d['nominal']>=1e13)throw new RuntimeException('Nominal harus lebih dari 0.');if(mb_strlen($d['nama_mustahik'])>100||mb_strlen($d['keterangan'])>255)throw new RuntimeException('Nama maksimal 100 dan keterangan maksimal 255 karakter.');if($pa==='update'){$m->update((int)($_POST['id']??0),$d);flash('Penyaluran dan jurnal berhasil diperbarui.');}else{$m->create($d);flash('Penyaluran dan jurnal berhasil disimpan.');}redirect('index.php?page=penyaluran');}catch(Throwable $e){$err=$e instanceof RuntimeException?$e->getMessage():'Gagal menyimpan penyaluran.';if(($_POST['form_action']??'')==='update')$edit=$m->getById((int)($_POST['id']??0));}}
 $this->view('penyaluran/index',['rows'=>$m->getAll(),'asnaf'=>$m->getAsnaf(),'err'=>$err,'edit'=>$edit,'title'=>'Penyaluran Dana']);}}
